#include <iostream>
#include <cstring>
#include <algorithm>
using namespace std;

using i64 = long long;
using u64 = unsigned long long;

constexpr int MAX_N = 250005, MAX_M = 1 << 17, MAX_D = 18;

int P;

int mod_exp(int base, int exp) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = (i64)result * base % P;
        base = (i64)base * base % P;
        exp >>= 1;
    }
    return result;
}

int L, K, factorial[MAX_N], n, m, bit_mask[20], inv_factorial[MAX_N], bit_count[MAX_N];
i64 suma[MAX_D][MAX_M], sumc[MAX_D][MAX_M];
u64 dp[MAX_D][MAX_M], temp[MAX_D][MAX_M];

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> L >> K >> P;

    factorial[0] = 1;
    for (int i = 1; i <= L; ++i) {
        factorial[i] = (i64)factorial[i - 1] * i % P;
        bit_count[i] = bit_count[i >> 1] + (i & 1);
    }

    i64 total = mod_exp(K, L);
    if (L & 1) {
        cout << total << '\n';
        return 0;
    }

    inv_factorial[L] = mod_exp(factorial[L], P - 2);
    for (int i = L; i > 0; --i) {
        inv_factorial[i - 1] = (i64)inv_factorial[i] * i % P;
    }

    for (int i = 1; (1 << i) <= L; ++i) {
        if (L >> i & 1) bit_mask[n++] = 1 << i;
    }

    m = 1 << n;

    for (int i = 0; i < m; ++i) {
        int sum_bits = 0;
        for (int j = 0; j < n; ++j) {
            if (i >> j & 1) sum_bits += bit_mask[j];
        }
        suma[bit_count[i]][i] = inv_factorial[sum_bits];
    }

    for (int t = 0; t <= n; ++t) {
        i64* arr = suma[t];
        for (int len = m; len >= 2; len >>= 1) {
            for (int j = 0, step = len >> 1; j < m; j += len) {
                for (int k = 0; k < step; ++k) {
                    arr[j + k + step] += arr[j + k];
                }
            }
        }
        for (int j = 0; j < m; ++j) arr[j] %= P;
    }

    for (int t = 0; t <= n; ++t) {
        memcpy(dp[t], suma[t], m << 3);
    }

    int revK = 0, cnt = 0;
    for (int temp_k = K; temp_k; temp_k >>= 1) {
        revK = (revK << 1) | (temp_k & 1);
        ++cnt;
    }
    --cnt;
    revK >>= 1;

    for (; cnt; --cnt, revK >>= 1) {
        for (int t = 0; t <= n; ++t) {
            memset(temp[t], 0, m << 3);
        }

        for (int a = 0; a <= n; ++a) {
            for (int b = 0; a + b <= n; ++b) {
                u64* f = temp[a + b];
                const u64* g = dp[a];
                const u64* h = dp[b];
                for (int j = 0; j < m; ++j) {
                    f[j] += g[j] * h[j];
                }
            }
        }

        for (int t = 0; t <= n; ++t) {
            for (int j = 0; j < m; ++j) {
                dp[t][j] = temp[t][j] % P;
            }
        }

        if (revK & 1) {
            for (int t = 0; t <= n; ++t) {
                memset(temp[t], 0, m << 3);
            }

            for (int a = 0; a <= n; ++a) {
                for (int b = 0; a + b <= n; ++b) {
                    u64* f = temp[a + b];
                    const u64* g = dp[a];
                    const i64* h = suma[b];
                    for (int j = 0; j < m; ++j) {
                        f[j] += g[j] * h[j];
                    }
                }
            }

            for (int t = 0; t <= n; ++t) {
                for (int j = 0; j < m; ++j) {
                    dp[t][j] = temp[t][j] % P;
                }
            }
        }
    }

    for (int t = 0; t <= n; ++t) {
        memcpy(sumc[t], dp[t], m << 3);
    }

    for (int t = 0; t <= n; ++t) {
        i64* arr = sumc[t];
        for (int len = 2; len <= m; len <<= 1) {
            for (int j = 0, step = len >> 1; j < m; j += len) {
                for (int k = 0; k < step; ++k) {
                    arr[j + k + step] -= arr[j + k];
                }
            }
        }
        for (int j = 0; j < m; ++j) {
            arr[j] = (arr[j] % P + P) % P;
        }
    }

    i64 ans = (total - sumc[n][(1 << n) - 1] * factorial[L] % P + P) % P;
    cout << ans << '\n';

    return 0;
}
